function announce(text){$('#announcer').textContent=text;}
function showToast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3200);}
function setPage(page){if(!['explore','essentials','faq'].includes(page))return;pause();state.page=page;$$('.page').forEach(el=>el.hidden=el.id!==`page-${page}`);$$('.main-nav [data-page]').forEach(btn=>{const yes=btn.dataset.page===page;btn.classList.toggle('active',yes);yes?btn.setAttribute('aria-current','page'):btn.removeAttribute('aria-current');});if(page==='essentials')renderLibrary();if(page==='explore')requestAnimationFrame(resizeGraph);window.scrollTo({top:0,behavior:state.reduced?'instant':'smooth'});}
function setInspector(panel){state.panel=panel;$('#explanation').hidden=panel!=='explain';$('#trace-panel').hidden=panel!=='trace';['explain','trace'].forEach(k=>{const b=$(`#tab-${k}`);b.classList.toggle('active',k===panel);b.setAttribute('aria-selected',String(k===panel));b.tabIndex=k===panel?0:-1;});if(panel==='trace')renderTrace();}
function setTechnical(on){state.technical=on;document.body.classList.toggle('technical',on);$('#simple-btn').classList.toggle('active',!on);$('#technical-btn').classList.toggle('active',on);$('#simple-btn').setAttribute('aria-pressed',String(!on));$('#technical-btn').setAttribute('aria-pressed',String(on));$('#node-gateway .node-label').textContent=on?'Omni Gateway':'Gateway';updateNodeLabels();renderExplanation(false);renderTrace();}
function updateNodeLabels(){const s=SCENARIOS[state.scenario];for(const id of ['agentA','agentB','toolA','toolB'])$(`#${id}-label`).textContent=s[id];$('#user-label').textContent=s.user;$('#agentA-desc').textContent=s.agentADesc;$('#agentB-desc').textContent=s.agentBDesc;$('#toolA-desc').textContent=state.technical?s.readTool:s.toolADesc;$('#toolB-desc').textContent=state.technical?s.writeTool:s.toolBDesc;$('#systemA-label').textContent=s.systemA;$('#systemB-label').textContent=s.systemB;$('#node-toolA').setAttribute('aria-label',`${s.toolA}, MCP server: explore`);$('#node-toolB').setAttribute('aria-label',`${s.toolB}, MCP server: explore`);$('#node-agentA').setAttribute('aria-label',`${s.agentA}: explore`);$('#node-agentB').setAttribute('aria-label',`${s.agentB}: explore`);}
function loadScenario(key){if(!SCENARIOS[key])return;pause();state.scenario=key;state.index=0;state.elapsed=0;state.finished=false;state.selected=null;steps=makeSteps(SCENARIOS[key]);const s=SCENARIOS[key];$('#request-quote').textContent=`\u201c${s.request}\u201d`;$('#request-eyebrow').textContent=s.requestLabel;$('#scenario-symbol').innerHTML=icon(s.icon);$('#scenario-select').value=key;$('#timeline-range').max=steps.length;updateNodeLabels();$('#diagram-viewport').scrollLeft=0;setInspector('explain');renderAll();announce(`Story selected: ${s.title}. Ready to play.`);}
function selectComponent(key,node){if(!COMPONENTS[key])return;pause();state.selected={key,node:node||COMPONENTS[key].map};setInspector('explain');renderExplanation();renderGraph();announce(`${COMPONENTS[key].title} selected. Playback paused.`);}
function renderExplanation(animate=true){const el=$('#explanation');let html='';
 if(state.selected){const c=COMPONENTS[state.selected.key];html=`<div class="panel-symbol">${icon(c.icon)}</div><div class="panel-kicker">${esc(c.tag)}</div><h2>${esc(c.title)}</h2><p class="panel-copy">${esc(state.technical?c.technical:c.simple)}</p><div class="panel-example"><span class="small-label">In plain terms</span><p>${esc(c.example)}</p></div><div class="panel-takeaway"><b>Why it matters</b>${esc(c.value)}</div><button class="panel-link" data-detail="${state.selected.key}">Go a little deeper ${icon('arrow')}</button>`;}
 else if(state.index===0){html=`<div class="panel-symbol">${icon('fabric')}</div><div class="panel-kicker">The big picture</div><h2>A team, not<br>another agent.</h2><p class="panel-copy">Agent Fabric helps your agents and tools work together, with shared discovery, coordination, governance, and visibility.</p><div class="panel-example"><span class="small-label">The idea</span><p>The broker coordinates.<br>The gateway enforces rules.<br>Specialists and tools do the work.</p></div><div class="panel-takeaway"><b>Follow the moving dot</b>Watch a request travel through the team. Each handoff gets a simple explanation here.</div>`;}
 else {const st=steps[state.index-1];html=`<div class="panel-symbol">${icon(st.icon)}</div><div class="panel-kicker">${esc(st.tag)}</div><h2>${esc(st.title)}</h2><p class="panel-copy">${esc(state.technical?st.technical:st.simple)}</p><div class="panel-example ${st.blocked?'blocked':''}"><span class="small-label">${st.blocked?'Illustrative policy result':'In this story'}</span><p>${esc(st.example)}</p></div>${state.technical?`<details class="payload"><summary>Illustrative payload (not a protocol schema)</summary><pre>${esc(st.payload)}</pre></details>`:''}<div class="panel-takeaway"><b>The takeaway</b>${esc(st.value)}</div><button class="panel-link" data-detail="${st.component}">Explore ${esc(COMPONENTS[st.component].title)} ${icon('arrow')}</button>`;}
 el.innerHTML=html;if(animate&&!state.reduced){el.classList.remove('reveal');void el.offsetWidth;el.classList.add('reveal');}}
function renderTrace(){const el=$('#trace-panel');el.innerHTML=`<h3>The request, step by step.</h3><p class="trace-note">An illustrative activity log. No live traffic, timings, or private model reasoning.</p>`+(state.index===0?`<div class="trace-empty">${icon('activity')}Your story will appear here.<br>Play the walkthrough to begin.</div>`:steps.slice(0,state.index).map((st,i)=>`<div class="trace-item ${st.blocked?'blocked':''}"><small>STEP ${String(i+1).padStart(2,'0')}${i===state.index-1&&!state.finished?' / CURRENT':''}</small><h4>${esc(st.title)}</h4><p>${esc(st.log)}</p>${state.technical?`<code>${esc(st.payload.split('\n').slice(0,2).join(' / '))}</code>`:''}</div>`).join(''));$('#log-count').textContent=state.index;}
function edgeColor(id){return id.startsWith('tool')?'#26877b':id.startsWith('agent')?'#4b78b9':'#7553d8';}
function renderGraph(){
 $$('.node').forEach(n=>n.classList.remove('active','selected','completed','inactive','blocked'));$$('.control-chip').forEach(n=>n.classList.remove('selected','live'));$$('.shield-marker').forEach(n=>n.classList.remove('active','blocked'));$$('.edge').forEach(n=>{n.classList.remove('active','complete');n.style.removeProperty('--edge-color');n.style.removeProperty('stroke-dasharray');n.style.removeProperty('marker-end');});$$('.edge-trace').forEach(n=>{n.classList.remove('active');n.style.removeProperty('stroke-dasharray');n.style.stroke=edgeColor(n.id.slice(6));});$('#packet-group').style.display='none';
 if(state.scenario==='blocked'){['agentB','toolB'].forEach(id=>$(`#node-${id}`).classList.add('inactive'));}
 if(state.index>0){const st=steps[state.index-1];steps.slice(0,state.index-1).forEach(prev=>prev.routes.filter(()=>!prev.blocked).forEach(r=>$(`#edge-${r.edge}`).classList.add('complete')));if(!state.selected){st.nodes.forEach(id=>$(`#node-${id}`).classList.add('active'));st.routes.forEach(r=>{const e=$(`#edge-${r.edge}`);e.classList.add('active');e.style.setProperty('--edge-color',st.blocked?'#bd5362':edgeColor(r.edge));$(`#trace-${r.edge}`).classList.add('active');if($(`#shield-${r.edge}`))$(`#shield-${r.edge}`).classList.add('active');});if(st.blocked)$('#shield-toolA').classList.add('blocked');if(st.component==='governance'||st.component==='gateway')$('#chip-governance').classList.add('live');if(st.component==='visualizer')$('#chip-visualizer').classList.add('live');}}
 if(state.scenario==='blocked'&&state.index>=5&&!state.selected){const e=$('#edge-toolA');e.classList.remove('complete');e.classList.add('active');e.style.setProperty('--edge-color','#bd5362');e.style.strokeDasharray=`${e.getTotalLength()*.5} ${e.getTotalLength()}`;e.style.markerEnd='none';$('#trace-toolA').classList.remove('active');$('#shield-toolA').classList.add('blocked');$('#node-toolA').classList.add('inactive');}
 if(state.selected){const id=state.selected.node;if($(`#node-${id}`))$(`#node-${id}`).classList.add('selected');if($(`#chip-${id}`))$(`#chip-${id}`).classList.add('selected');if(id==='governance')$$('.shield-marker').forEach(n=>n.classList.add('active'));if(id==='visualizer')$$('.node').forEach(n=>n.classList.add('completed'));}
 $('#graph').classList.toggle('paused',!state.playing);$('#flow-status').textContent=state.selected?'Exploring a component':state.index?state.finished?'Story complete':state.playing?'Follow the request':'Walkthrough paused':'The connected team';if(state.index&&!state.selected)renderPacket();
}
function renderControls(){const finished=state.finished&&state.index===steps.length;$('#play-btn').innerHTML=icon(state.playing?'pause':finished?'reset':'play')+`<span>${state.playing?'Pause the story':finished?'Play it again':state.index?'Continue story':'Play the story'}</span>`;$('#play-btn').setAttribute('aria-label',state.playing?'Pause the walkthrough':finished?'Replay the walkthrough':'Play the walkthrough');$('#prev-btn').disabled=state.index===0;$('#next-btn').disabled=state.index===steps.length;$('#timeline-range').value=state.index;$('#timeline-range').style.setProperty('--progress',`${state.index/steps.length*100}%`);$('#timeline-range').setAttribute('aria-valuetext',state.index?`Step ${state.index} of ${steps.length}: ${steps[state.index-1].title}`:'Ready to explore');$('#step-counter').textContent=state.index?`${String(state.index).padStart(2,'0')} / ${steps.length}${finished?' \u00b7 Complete':''}`:'Ready to explore';$('#current-step').textContent=state.index?steps[state.index-1].title:"One request. Let's follow it.";$('#graph').classList.toggle('paused',!state.playing);}
function renderAll(){renderExplanation();renderGraph();renderControls();renderTrace();}
function duration(){return (state.index?steps[state.index-1].duration:0)||5600;}
function renderPacket(){const st=steps[state.index-1];if(!st||!st.routes.length||state.selected){$('#packet-group').style.display='none';return;}const progress=Math.min(state.elapsed/duration(),.999999);const motion=state.reduced?.5:Math.min(progress/.86,.999999);const count=st.routes.length;const active=Math.min(Math.floor(motion*count),count-1);const r=st.routes[active];const path=$(`#edge-${r.edge}`);let fraction=state.reduced?.5:(motion*count-active);fraction=Math.max(0,Math.min(1,fraction));let position=r.reverse?r.limit*(1-fraction):r.limit*fraction;const p=path.getPointAtLength(path.getTotalLength()*position);const color=st.blocked?'#bd5362':edgeColor(r.edge);const viewport=$('#diagram-viewport');if(state.playing&&viewport.scrollWidth>viewport.clientWidth+2){const scale=$('#graph-wrap').getBoundingClientRect().width/1000;const desired=Math.max(0,Math.min(viewport.scrollWidth-viewport.clientWidth,p.x*scale-viewport.clientWidth*.5));viewport.scrollLeft+=(desired-viewport.scrollLeft)*.12;}$('#packet-group').style.display='';for(const id of ['packet','packet-halo']){const e=$(`#${id}`);e.setAttribute('cx',p.x);e.setAttribute('cy',p.y);e.style.fill=color;}}
function frame(now){if(!state.playing)return;if(state.lastTime)state.elapsed+=Math.min(now-state.lastTime,100)*state.speed;state.lastTime=now;if(state.elapsed>=duration()){
 if(state.index>=steps.length){state.finished=true;pause();renderAll();announce('Walkthrough complete. Replay it or explore another story.');return;}
 state.index++;state.elapsed=0;state.selected=null;renderAll();announce(`Step ${state.index}: ${steps[state.index-1].title}.`);
 }renderPacket();state.raf=requestAnimationFrame(frame);}
function play(){if(state.page!=='explore')setPage('explore');if(state.finished||state.index===0){state.index=1;state.elapsed=0;state.finished=false;}state.selected=null;state.playing=true;state.lastTime=0;setInspector('explain');renderAll();cancelAnimationFrame(state.raf);state.raf=requestAnimationFrame(frame);announce(`Playing. Step ${state.index}: ${steps[state.index-1].title}.`);}
function pause(){state.playing=false;state.lastTime=0;cancelAnimationFrame(state.raf);if($('#play-btn'))renderControls();if($('#flow-status'))$('#flow-status').textContent=state.selected?'Exploring a component':state.index?state.finished?'Story complete':'Walkthrough paused':'The connected team';}
function goStep(index){pause();state.index=Math.max(0,Math.min(steps.length,index));state.elapsed=0;state.selected=null;state.finished=state.index===steps.length;setInspector('explain');renderAll();announce(state.index?`Step ${state.index}: ${steps[state.index-1].title}.`:'Walkthrough reset.');}
function reset(){goStep(0);$('#diagram-viewport').scrollLeft=0;}
function resizeGraph(){const wrap=$('#graph-wrap');const width=wrap.getBoundingClientRect().width;if(!width)return;const scale=width/1000;$('#graph').style.setProperty('--graph-scale',scale);wrap.style.height=`${300*scale}px`;}
function renderLibrary(){const search=$('#component-search').value.toLowerCase().trim();const entries=Object.entries(COMPONENTS).filter(([key,c])=>key!=='user'&&(state.filter==='all'||c.category===state.filter)&&`${c.title} ${c.short} ${c.technical}`.toLowerCase().includes(search));$('#component-grid').innerHTML=entries.length?entries.map(([key,c])=>`<button class="component-card" data-detail="${key}"><span class="card-icon">${icon(c.icon)}</span><span class="card-category">${esc(c.category)}</span><h3>${esc(c.title)}</h3><p>${esc(c.short)}</p><span class="card-more">Get to know it ${icon('arrow')}</span></button>`).join(''):'<div class="empty-search">No matching components. Try a different word or select All components.</div>';}
function renderFAQ(){$('#faq-list').innerHTML=FAQS.map(([q,a,src],i)=>`<details class="faq-item" ${i===0?'open':''}><summary>${esc(q)}</summary><div class="answer">${esc(a)}<br>${sourceLink(src,'Explore the source')}</div></details>`).join('');}
function openModal(type,key){pause();let title='',html='';if(type==='detail'){const c=COMPONENTS[key];if(!c)return;title='The essentials';html=`<div class="card-icon">${icon(c.icon)}</div><div class="eyebrow">${esc(c.tag)}</div><h2>${esc(c.title)}</h2><p>${esc(c.simple)}</p><div class="detail-columns"><div class="detail-block"><h3>Under the surface</h3><p>${esc(c.technical)}</p></div><div class="detail-block"><h3>A practical example</h3><p>${esc(c.example)}</p></div></div><div class="detail-note">${esc(c.note)}</div><p><strong style="color:var(--ink);font-weight:600">Why it matters:</strong> ${esc(c.value)}</p><div class="modal-actions"><button class="secondary-btn" data-locate="${key}">See it in the story ${icon('arrow')}</button><div>${sourceLink(c.source)}${c.extraSource?`<br>${sourceLink(c.extraSource,'Related documentation')}`:''}</div></div>`;}
 else if(type==='sources'){title='Documentation & scope';html=`<div class="eyebrow">Built to explain, not to impersonate</div><h2>A guide with its sources.</h2><p>Product concepts were checked against the official pages below on <strong>11 November 2026</strong>. Documentation, terminology, supported features, and deployment requirements can change.</p><div class="detail-note">This is an independent educational concept, not an official MuleSoft product UI. Scenarios, agent names, IDs, payloads, and results are fictional. There are no live systems, analytics trackers, API keys, or measured performance claims.</div><p>The animation is a logical teaching model. Registry and visualization are management capabilities, not required serial request hops. Shield markers compress configured gateway enforcement; real ingress and egress topology varies. The blocked-tool story is an illustrative access-control outcome, not a policy implementation.</p><div class="source-list">${Object.values(SOURCES).map(s=>`<a class="source-row" href="${s.url}" target="_blank" rel="noopener noreferrer"><div><strong>${esc(s.title)}</strong><span>${esc(s.detail)}</span></div>${icon('external')}</a>`).join('')}</div><div class="detail-note">MuleSoft, Salesforce, Agentforce, and related product names are trademarks of their respective owners. Older references may use Flex Gateway; the current gateway documentation uses Omni Gateway.</div>`;}
 else if(type==='intro'){title='The 30-second idea';html=`<div class="eyebrow">Start here</div><h2>Your specialists.<br>Working as a team.</h2><p>Imagine a customer asks about a late delivery. One specialist knows orders. Another handles customer care. Your existing systems hold the facts. Agent Fabric helps connect those capabilities with control and visibility.</p><div class="intro-steps"><div class="intro-step">${icon('grid')}<h3>Discover</h3><p>Find the capabilities already available through the registry and supported scanners.</p></div><div class="intro-step">${icon('broker')}<h3>Orchestrate</h3><p>Use a broker when the task needs coordinated work across specialists and tools.</p></div><div class="intro-step">${icon('shield')}<h3>Govern</h3><p>Configure policies and enforce them on protected interaction paths.</p></div><div class="intro-step">${icon('eye')}<h3>Observe</h3><p>Understand the network, its interactions, and its governance coverage.</p></div></div><div class="modal-actions"><button class="secondary-btn" id="intro-play">Watch one request ${icon('play')}</button>${sourceLink('overview')}</div>`;}
 else {title='Make the walkthrough your own';html=`<div class="eyebrow">A little help</div><h2>Watch. Pause. Explore.</h2><p>Choose a story, then play it or move one step at a time. Click any component to pause and explore it. Switch to Technical for protocol labels and illustrative payloads. The Request log collects the story so far.</p><div class="shortcut-grid"><span><kbd>Space</kbd>Play or pause</span><span><kbd>&larr;</kbd>Previous step</span><span><kbd>&rarr;</kbd>Next step</span><span><kbd>R</kbd>Restart the story</span><span><kbd>Esc</kbd>Close a dialog</span><span><kbd>Tab</kbd>Move between controls</span></div><div class="detail-note">On a narrow screen, the map follows the moving dot. Touch the map to pause, then swipe horizontally. Reduce motion is honored automatically from your system preference. Playback pauses when the browser tab is hidden. Opening a component or a dialog also pauses the story.</div><p>Presentation mode reduces surrounding content. The fullscreen control uses browser fullscreen when available, and falls back to the presentation layout when it is not.</p>`;}
 $('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){$('#modal').close();}
async function togglePresentation(){const on=!document.body.classList.contains('presenting');document.body.classList.toggle('presenting',on);$('#present-btn').setAttribute('aria-pressed',String(on));$('#present-btn').setAttribute('aria-label',on?'Exit presentation mode':'Enter presentation mode');try{if(on&&document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else if(!on&&document.fullscreenElement)await document.exitFullscreen();}catch(e){showToast(on?'Presentation layout enabled. Fullscreen is not available in this browser context.':'Presentation mode ended.');}setTimeout(resizeGraph,50);}
// Event delegation keeps generated cards and explanations keyboard-accessible.
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.page){setPage(b.dataset.page);return;}if(b.dataset.component){const node=b.id.startsWith('node-')?b.id.slice(5):b.id.startsWith('chip-')?b.id.slice(5):'governance';selectComponent(b.dataset.component,node);return;}if(b.dataset.detail){openModal('detail',b.dataset.detail);return;}if(b.dataset.modal){openModal(b.dataset.modal);return;}if(b.dataset.locate){const key=b.dataset.locate;closeModal();setPage('explore');selectComponent(key,COMPONENTS[key].map);const target=$(`#node-${COMPONENTS[key].map}`);if(target)setTimeout(()=>target.scrollIntoView({behavior:state.reduced?'instant':'smooth',block:'nearest',inline:'center'}),70);return;}if(b.dataset.filter){state.filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderLibrary();return;}if(b.id==='intro-play'){closeModal();setPage('explore');play();}});
$('#diagram-viewport').addEventListener('pointerdown',()=>{if(state.playing)pause();});
$('#play-btn').addEventListener('click',()=>state.playing?pause():play());$('#reset-btn').addEventListener('click',reset);$('#prev-btn').addEventListener('click',()=>goStep(state.index-1));$('#next-btn').addEventListener('click',()=>goStep(state.index+1));$('#timeline-range').addEventListener('input',e=>goStep(Number(e.target.value)));$('#scenario-select').addEventListener('change',e=>loadScenario(e.target.value));$('#speed-select').addEventListener('change',e=>state.speed=Number(e.target.value));$('#simple-btn').addEventListener('click',()=>setTechnical(false));$('#technical-btn').addEventListener('click',()=>setTechnical(true));$('#tab-explain').addEventListener('click',()=>setInspector('explain'));$('#tab-trace').addEventListener('click',()=>setInspector('trace'));$('#component-search').addEventListener('input',renderLibrary);$('#modal-close').addEventListener('click',closeModal);$('#present-btn').addEventListener('click',togglePresentation);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$$('[role="tab"]').forEach(tab=>tab.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const next=tab.id==='tab-explain'?'trace':'explain';setInspector(next);$(`#tab-${next}`).focus();}}));
document.addEventListener('keydown',e=>{const target=e.target;if($('#modal').open||e.altKey||e.ctrlKey||e.metaKey||target.closest('input,select,textarea,[contenteditable="true"],[role="tab"]'))return;if(state.page!=='explore')return;if(e.code==='Space'){if(target.closest('button,a,summary'))return;e.preventDefault();state.playing?pause():play();}else if(e.key==='ArrowRight'){e.preventDefault();goStep(state.index+1);}else if(e.key==='ArrowLeft'){e.preventDefault();goStep(state.index-1);}else if(e.key.toLowerCase()==='r'){e.preventDefault();reset();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.playing){pause();announce('Playback paused because the page is not visible.');}});
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&document.body.classList.contains('presenting')){document.body.classList.remove('presenting');$('#present-btn').setAttribute('aria-pressed','false');$('#present-btn').setAttribute('aria-label','Enter presentation mode');resizeGraph();}});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',e=>{state.reduced=e.matches;renderPacket();});
// Duplicate geometry for the subtle flow overlay; one moving packet shows direction.
$$('.edge').forEach(edge=>{const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.id=`trace-${edge.id.slice(5)}`;p.setAttribute('d',edge.getAttribute('d'));p.setAttribute('class','edge-trace');p.style.stroke=edgeColor(edge.id.slice(5));$('#traces').appendChild(p);});
new ResizeObserver(resizeGraph).observe($('#graph-wrap'));renderFAQ();renderLibrary();loadScenario('order');$$('.page').forEach(el=>el.hidden=el.id!=='page-explore');requestAnimationFrame(resizeGraph);
